fn highlighted_text_ranges(text: &str, query: &str) -> Vec<(usize, usize)> {
    let query_words: Vec<String> = query
        .to_lowercase()
        .split_whitespace()
        .map(|w| w.to_string())
        .filter(|w| !w.is_empty())
        .collect();
    if query_words.is_empty() {
        return Vec::new();
    }

    let chars: Vec<char> = text.chars().collect();
    let mut matches = Vec::new();

    for word in &query_words {
        let word_len = word.chars().count();
        if word_len == 0 || word_len > chars.len() {
            continue;
        }

        let mut start = 0;
        while start + word_len <= chars.len() {
            let segment: String = chars[start..start + word_len]
                .iter()
                .collect::<String>()
                .to_lowercase();
            if segment == *word {
                matches.push((start, start + word_len));
                start += word_len;
            } else {
                start += 1;
            }
        }
    }

    matches.sort_by_key(|r| r.0);
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for r in matches {
        if let Some(last) = merged.last_mut() {
            if r.0 <= last.1 {
                last.1 = last.1.max(r.1);
            } else {
                merged.push(r);
            }
        } else {
            merged.push(r);
        }
    }
    merged
}


fn main() { assert_eq!(highlighted_text_ranges("Alpha beta", "alpha"), vec![(0,5)]); assert_eq!(highlighted_text_ranges("привет", "привет"),vec![(0,6)]); assert!(highlighted_text_ranges("İ", "İ").is_empty()); println!("ASCII/Cyrillic controls passed; identical capital dotted-I has no highlight"); }
